import sys

def sort_brute(nums):
    cnt = [0, 0, 0]
    for x in nums:
        cnt[x] += 1
    i = 0
    for c in range(3):
        for _ in range(cnt[c]):
            nums[i] = c
            i += 1
    return nums

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(' '.join(map(str, sort_brute(nums))))

import sys

def sort_opt(nums):
    lo, mid, hi = 0, 0, len(nums) - 1
    while mid <= hi:
        if nums[mid] == 0:
            nums[lo], nums[mid] = nums[mid], nums[lo]
            lo += 1
            mid += 1
        elif nums[mid] == 2:
            nums[mid], nums[hi] = nums[hi], nums[mid]
            hi -= 1
        else:
            mid += 1
    return nums

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(' '.join(map(str, sort_opt(nums))))

import sys

def sort_best(nums):
    zero, cur = 0, 0
    two = len(nums) - 1
    while cur <= two:
        if nums[cur] == 0:
            nums[zero], nums[cur] = nums[cur], nums[zero]
            zero += 1
            cur += 1
        elif nums[cur] == 2:
            nums[two], nums[cur] = nums[cur], nums[two]
            two -= 1
        else:
            cur += 1
    return nums

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(' '.join(map(str, sort_best(nums))))
